using OrdersService.Clients;using OrdersService.Models;using OrdersService.Services;namespace OrdersService.Endpoints;public static class OrderEndpoints{public static void MapOrderEndpoints(this WebApplication app){app.MapGet("/health",()=>Results.Ok(new{service="orders",status="healthy"}));app.MapGet("/api/orders",(OrderStore s)=>Results.Ok(s.GetAll()));app.MapGet("/api/orders/{id:int}",(int id,OrderStore s)=>{var x=s.Get(id);return x is null?Results.NotFound():Results.Ok(x);});app.MapPost("/api/orders",async(CreateOrderRequest r,CatalogClient catalog,OrderStore store,CancellationToken ct)=>{if(r.SubjectId<=0||string.IsNullOrWhiteSpace(r.CandidateName)||string.IsNullOrWhiteSpace(r.ExamSession))return Results.BadRequest(new{error="SubjectId, candidateName and examSession are required."});var lookup=await catalog.GetSubjectAsync(r.SubjectId,ct);if(lookup.Status==CatalogLookupStatus.NotFound)return Results.BadRequest(new{error=$"Subject {r.SubjectId} does not exist."});if(lookup.Status==CatalogLookupStatus.Unavailable)return Results.Problem(title="Catalog service unavailable",detail="The order was not created. Retry after Catalog is available.",statusCode=503);var order=store.Add(r,lookup.Subject!.Name);return Results.Created($"/api/orders/{order.Id}",order);});}}